import re

COMPARE = ("against", "than", "from", "versus", "compared", "slowest", "fastest")

def classify(text):
    t = text.lower()
    has_number = bool(re.search(r"\d", t))
    has_comparison = any(w in t for w in COMPARE)
    has_action = any(w in t for w in ("recommend", "should", "review", "investigate"))
    if has_number and has_comparison and has_action:
        return "recommendation"
    if has_number and has_comparison:
        return "insight"
    if has_number:
        return "observation"
    return "none"

for s in ["Germany revenue was 19,447.50.", "Germany is 29.0% of revenue, more than any other market.", "Germany should be the first market to receive the new product, since it is 29.0% of revenue against 20.9% for the UK.", "Markets are listed below."]:
    print(classify(s))
